import "server-only";
import { db } from "@/lib/db";
export async function markApplicationActivity(
  userId: string,
  now = new Date(),
) {
  return db.user.updateMany({
    where: {
      id: userId,
      deletionRequestedAt: null,
      OR: [
        { lastActiveAt: null },
        { lastActiveAt: { lte: new Date(+now - 15 * 60000) } },
      ],
    },
    data: { lastActiveAt: now },
  });
}
